&reftitle.description;
public Yaf_Request_AbstractnullYaf_Request_Abstract::setControllerName stringcontroller boolformat_nametrue
Définit le nom du contrôleur dans la requête ; ceci est habituellement utilisé par un routeur personnalisé pour définir le nom du contrôleur résultant du routage.

  &reftitle.examples;

   Exemple avec Yaf_Request_Abstract::setControllerName


<?php
class RestRouter extends Yaf_Route_Interface
{
    public function route(Yaf_Request_Abstract $request)
    {
        if (0 === strpos($request->getRequestUri(), "/api")) {
            // Les noms sont formatés en style camel par défaut,
            // ainsi "order_item" devient "Order_Item"
            $request->setControllerName("order_item")
                    ->setActionName("list");
            return true;
        }

        return false;
    }

    public function assemble(array $info, array $query = null) {}
}
?>
